                m.insert(QString::fromUtf8(u8"Port must be a number from 1 to 65535."), QString::fromUtf8(u8"\u041F\u043E\u0440\u0442 \u0434\u043E\u043B\u0436\u0435\u043D \u0431\u044B\u0442\u044C \u0447\u0438\u0441\u043B\u043E\u043C \u043E\u0442 1 \u0434\u043E 65535."));
                m.insert(QString::fromUtf8(u8"The build name is locked by build.ini (complete=true)."), QString::fromUtf8(u8"\u041D\u0430\u0437\u0432\u0430\u043D\u0438\u0435 \u0441\u0431\u043E\u0440\u043A\u0438 \u0437\u0430\u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u0430\u043D\u043E build.ini (complete=true)."));
