                m.insert(QString::fromUtf8(u8"<html><head/><body><p>Enable shadows exclusively for the player character. May have a very minor performance impact.</p></body></html>"), QString::fromUtf8(u8"<html><head/><body><p>\u0412\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u0442\u0435\u043D\u0438 \u0442\u043E\u043B\u044C\u043A\u043E \u0434\u043B\u044F \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u0436\u0430 \u0438\u0433\u0440\u043E\u043A\u0430. \u0412\u043B\u0438\u044F\u043D\u0438\u0435 \u043D\u0430 \u043F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C \u043E\u0431\u044B\u0447\u043D\u043E \u043C\u0438\u043D\u0438\u043C\u0430\u043B\u044C\u043D\u043E.</p></body></html>"));
                m.insert(QString::fromUtf8(u8"<html><head/><body><p>Enable shadows for NPCs and creatures besides the player character. May have a minor performance impact.</p></body></html>"), QString::fromUtf8(u8"<html><head/><body><p>\u0412\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u0442\u0435\u043D\u0438 \u0434\u043B\u044F NPC \u0438 \u0441\u0443\u0449\u0435\u0441\u0442\u0432 \u043F\u043E\u043C\u0438\u043C\u043E \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u0436\u0430 \u0438\u0433\u0440\u043E\u043A\u0430. \u041C\u043E\u0436\u0435\u0442 \u043D\u0435\u043C\u043D\u043E\u0433\u043E \u0441\u043D\u0438\u0437\u0438\u0442\u044C \u043F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C.</p></body></html>"));
                m.insert(QString::fromUtf8(u8"<html><head/><body><p>Enable shadows for primarily inanimate objects. May have a significant performance impact.</p></body></html>"), QString::fromUtf8(u8"<html><head/><body><p>\u0412\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u0442\u0435\u043D\u0438 \u0432 \u043E\u0441\u043D\u043E\u0432\u043D\u043E\u043C \u0434\u043B\u044F \u0441\u0442\u0430\u0442\u0438\u0447\u043D\u044B\u0445 \u043E\u0431\u044A\u0435\u043A\u0442\u043E\u0432. \u041C\u043E\u0436\u0435\u0442 \u0437\u0430\u043C\u0435\u0442\u043D\u043E \u0441\u043D\u0438\u0437\u0438\u0442\u044C \u043F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C.</p></body></html>"));
                m.insert(QString::fromUtf8(u8"<html><head/><body><p>Enable shadows for the terrain including distant terrain. May have a significant performance and shadow quality impact.</p></body></html>"), QString::fromUtf8(u8"<html><head/><body><p>\u0412\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u0442\u0435\u043D\u0438 \u043B\u0430\u043D\u0434\u0448\u0430\u0444\u0442\u0430, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u0434\u0430\u043B\u044C\u043D\u0438\u0439 \u043B\u0430\u043D\u0434\u0448\u0430\u0444\u0442. \u041C\u043E\u0436\u0435\u0442 \u0437\u0430\u043C\u0435\u0442\u043D\u043E \u0432\u043B\u0438\u044F\u0442\u044C \u043D\u0430 \u043F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C \u0438 \u043A\u0430\u0447\u0435\u0441\u0442\u0432\u043E \u0442\u0435\u043D\u0435\u0439.</p></body></html>"));
                m.insert(QString::fromUtf8(u8"<html><head/><body><p>Due to limitations with Morrowind's data, only actors can cast shadows indoors, which some might feel is distracting.</p><p>Has no effect if actor/player shadows are not enabled.</p></body></html>"), QString::fromUtf8(u8"<html><head/><body><p>\u0418\u0437-\u0437\u0430 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u0439 \u0434\u0430\u043D\u043D\u044B\u0445 Morrowind \u0432 \u0438\u043D\u0442\u0435\u0440\u044C\u0435\u0440\u0430\u0445 \u043F\u043E\u043B\u043D\u043E\u0446\u0435\u043D\u043D\u044B\u0435 \u0442\u0435\u043D\u0438 \u043C\u043E\u0433\u0443\u0442 \u043E\u0442\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0442\u044C \u0442\u043E\u043B\u044C\u043A\u043E \u0430\u043A\u0442\u0451\u0440\u044B, \u0447\u0442\u043E \u0438\u043D\u043E\u0433\u0434\u0430 \u0432\u044B\u0433\u043B\u044F\u0434\u0438\u0442 \u043D\u0435\u043F\u0440\u0438\u0432\u044B\u0447\u043D\u043E.</p><p>\u041D\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442, \u0435\u0441\u043B\u0438 \u0442\u0435\u043D\u0438 NPC/\u0438\u0433\u0440\u043E\u043A\u0430 \u043E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u044B.</p></body></html>"));
                m.insert(QString::fromUtf8(u8"<html><head/><body><p>Type of \"compute scene bounds\" computation method to be used. Bounds (default) for good balance between performance and shadow quality, primitives for better looking shadows or none for no computation.</p></body></html>"), QString::fromUtf8(u8"<html><head/><body><p>\u041C\u0435\u0442\u043E\u0434 \u0440\u0430\u0441\u0447\u0451\u0442\u0430 \u0433\u0440\u0430\u043D\u0438\u0446 \u0441\u0446\u0435\u043D\u044B \u0434\u043B\u044F \u0442\u0435\u043D\u0435\u0439. \u00AB\u0413\u0440\u0430\u043D\u0438\u0446\u044B\u00BB \u2014 \u0445\u043E\u0440\u043E\u0448\u0438\u0439 \u0431\u0430\u043B\u0430\u043D\u0441 \u043F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u0438 \u0438 \u043A\u0430\u0447\u0435\u0441\u0442\u0432\u0430, \u00AB\u041F\u0440\u0438\u043C\u0438\u0442\u0438\u0432\u044B\u00BB \u2014 \u0431\u043E\u043B\u0435\u0435 \u043A\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0435 \u0442\u0435\u043D\u0438, \u00AB\u041D\u0435\u0442\u00BB \u2014 \u0431\u0435\u0437 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0440\u0430\u0441\u0447\u0451\u0442\u0430.</p></body></html>"));
                m.insert(QString::fromUtf8(u8"<html><head/><body><p>The resolution of each individual shadow map. Increasing it significantly improves shadow quality but may have a minor performance impact.</p></body></html>"), QString::fromUtf8(u8"<html><head/><body><p>\u0420\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0438\u0435 \u043A\u0430\u0436\u0434\u043E\u0439 \u043A\u0430\u0440\u0442\u044B \u0442\u0435\u043D\u0435\u0439. \u0423\u0432\u0435\u043B\u0438\u0447\u0435\u043D\u0438\u0435 \u0437\u0430\u043C\u0435\u0442\u043D\u043E \u0443\u043B\u0443\u0447\u0448\u0430\u0435\u0442 \u043A\u0430\u0447\u0435\u0441\u0442\u0432\u043E \u0442\u0435\u043D\u0435\u0439, \u043D\u043E \u043C\u043E\u0436\u0435\u0442 \u043D\u0435\u043C\u043D\u043E\u0433\u043E \u0441\u043D\u0438\u0437\u0438\u0442\u044C \u043F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C.</p></body></html>"));
                m.insert(QString::fromUtf8(u8"<html><head/><body><p>The distance from the camera at which shadows completely disappear.</p></body></html>"), QString::fromUtf8(u8"<html><head/><body><p>\u0420\u0430\u0441\u0441\u0442\u043E\u044F\u043D\u0438\u0435 \u043E\u0442 \u043A\u0430\u043C\u0435\u0440\u044B, \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u0442\u0435\u043D\u0438 \u043F\u043E\u043B\u043D\u043E\u0441\u0442\u044C\u044E \u0438\u0441\u0447\u0435\u0437\u0430\u044E\u0442.</p></body></html>"));
                m.insert(QString::fromUtf8(u8"<html><head/><body><p>64 game units is 1 real life yard or about 0.9 m</p></body></html>"), QString::fromUtf8(u8"<html><head/><body><p>64 \u0438\u0433\u0440\u043E\u0432\u044B\u0435 \u0435\u0434\u0438\u043D\u0438\u0446\u044B \u2014 \u043F\u0440\u0438\u043C\u0435\u0440\u043D\u043E 0,9 \u043C.</p></body></html>"));
                m.insert(QString::fromUtf8(u8"<html><head/><body><p>The fraction of the limit above at which shadows begin to gradually fade away.</p></body></html>"), QString::fromUtf8(u8"<html><head/><body><p>\u0414\u043E\u043B\u044F \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u0439 \u0432\u044B\u0448\u0435 \u0434\u0430\u043B\u044C\u043D\u043E\u0441\u0442\u0438, \u0441 \u043A\u043E\u0442\u043E\u0440\u043E\u0439 \u0442\u0435\u043D\u0438 \u043D\u0430\u0447\u0438\u043D\u0430\u044E\u0442 \u043F\u043E\u0441\u0442\u0435\u043F\u0435\u043D\u043D\u043E \u0438\u0441\u0447\u0435\u0437\u0430\u0442\u044C.</p></body></html>"));
                m.insert(QString::fromUtf8(u8"Choose a preset, then fine-tune only the settings you need."), QString::fromUtf8(u8"Выберите пресет, затем при необходимости измените только нужные параметры."));
                m.insert(QString::fromUtf8(u8"Auto"), QString::fromUtf8(u8"Авто"));
                m.insert(QString::fromUtf8(u8"Balance"), QString::fromUtf8(u8"Баланс"));
